    '\\label{eq:subsample-dev} \\|\\hat V - V\\|_{\\mathrm{op}} \\;\\le\\; mB\\sqrt{\\frac{2L}{n}} \\;+\\; \\frac{4\\,mB\\,L}{3\\,n}.',
