    '\\label{eq:transported-score-new} U_t(a)=m_t(a) +\\beta_t e^{\\bar D_t/2}\\sqrt{\\kappa_{+,t}}\\,\\hat s_t(a) +b_t(a),',
    '\\label{eq:variance} s_{\\Calg,t}^2(a) \\;=\\; \\bg_t(a)^\\top\\Calg_t^{-1}\\,\\bg_t(a).',
    '\\label{eq:vdyn-def} \\Valg_T := \\sum_{t=1}^T \\bigl[-\\log\\det(\\bI+\\Xi_t)\\bigr]_+, \\qquad \\Gamdyn_T := \\log\\frac{\\det(\\Calg_{T+1})}{\\det(\\lambda\\bI)} + \\Valg_T,',
    '\\label{eq:whitened-cols} \\Gmat_t := \\Bigl[\\,\\bCbar_t^{-1/2}\\bg_s/\\sigma\\,\\Bigr]_{s<t}, \\qquad \\Dmat_t := \\Bigl[\\,\\bCbar_t^{-1/2}\\delta_{s,t}/\\sigma\\,\\Bigr]_{s<t}, \\qquad \\chi_t := \\|\\Dmat_t\\|_{\\mathrm{op}} .',
    '\\label{eq:width-sum-dyn} \\sum_{t=1}^T s_{\\Calg,t}^2(a_t) \\;\\le\\; (\\sigma^2+G^2/\\lambda)\\,\\Lamalg_T \\;\\le\\; (\\sigma^2+G^2/\\lambda)\\,\\Gamdyn_T .',
    '\\label{eq:xi-def} \\Xi_t \\;:=\\; (\\Calg_t^{+})^{-1/2}\\,(\\Calg_{t+1}-\\Calg_t^{+})\\, (\\Calg_t^{+})^{-1/2},',
